code='''def transform(grid):
    g=[row[:] for row in grid]; h,w=len(g),len(g[0])
    for r in range(h-1):
      for c in range(w-1):
        if all(grid[y][x]==2 for y in (r,r+1) for x in (c,c+1)):
          # source corner colors in clockwise order are reassigned to four outward diagonals
          sources=[(r-1,c-1),(r-1,c+2),(r+2,c-1),(r+2,c+2)]
          vals=[grid[y][x] if 0<=y<h and 0<=x<w else 0 for y,x in sources]
          # top-left beam takes bottom-left color; top-right takes top-left;
          # bottom-left takes bottom-right; bottom-right takes top-right
          colors=[vals[2], vals[0], vals[3], vals[1]]
          dirs=[(-1,-1),(-1,1),(1,-1),(1,1)]
          starts=[(r-1,c-1),(r-1,c+2),(r+2,c-1),(r+2,c+2)]
          for (y,x), (dy,dx),col in zip(starts,dirs,colors):
            if col and 0<=y<h and 0<=x<w:
              while 0<=y<h and 0<=x<w:
                g[y][x]=col;y+=dy;x+=dx
    return g
'''
